#!/usr/bin/env bash
# Rust/Cargo.lock -> generated web glue, declarations, WASM and SHA256SUMS.
# --check builds in a temporary directory and compares every generated byte.
set -euo pipefail
cd "$(dirname "$0")"
mode="${1:-build}"
if [[ "$mode" != build && "$mode" != --check ]] || [[ $# -gt 1 ]]; then
  echo 'usage: build-wasm.sh [--check]' >&2
  exit 64
fi
cargo_bin="${SOLANA_CARGO_BIN:-cargo}"
bindgen_bin="${SOLANA_WASM_BINDGEN:-wasm-bindgen}"
rustc_bin="${RUSTC:-rustc}"
case "$("$rustc_bin" --version)" in
  'rustc 1.93.0 '*) ;;
  *) echo 'Rust 1.93.0 is required' >&2; exit 1 ;;
esac
# Cargo includes host build-script/proc-macro identities in target crate metadata.
# Source path remapping alone does not make cross-host builds byte-identical.
if [[ "$("$rustc_bin" -vV | sed -n 's/^host: //p')" != x86_64-unknown-linux-gnu ]]; then
  echo 'Canonical Solana WASM generation requires Rust host x86_64-unknown-linux-gnu; other hosts consume the tracked package' >&2
  exit 1
fi
test "$("$bindgen_bin" --version)" = 'wasm-bindgen 0.2.129'
# Panic locations otherwise contain machine-specific registry/source paths.
# Pin these flags too: caller flags cannot silently change the packaged implementation.
if [[ -n "${RUSTFLAGS:-}" || -n "${CARGO_ENCODED_RUSTFLAGS:-}" ]]; then
  echo 'Unset external Rust flags for the reproducible package build' >&2
  exit 1
fi
repo_root="$(cd ../../.. && pwd -P)"
cargo_home="${CARGO_HOME:-$HOME/.cargo}"
export RUSTFLAGS="--remap-path-prefix=$cargo_home=/cargo-home --remap-path-prefix=$repo_root=/frank"
output="$(mktemp -d "${TMPDIR:-/tmp}/frank-solana-wasm-build.XXXXXX")"
trap 'rm -rf "$output"' EXIT
"$cargo_bin" build --offline --locked --release --target wasm32-unknown-unknown \
  --message-format=json-render-diagnostics > "$output/cargo.jsonl"
artifact="$(python3 - "$output/cargo.jsonl" <<'PY'
import json, sys
artifacts = []
for line in open(sys.argv[1]):
    record = json.loads(line)
    if record.get('reason') == 'compiler-artifact' and record['target']['name'] == 'frank_experimental_solana_crypto_backend':
        artifacts.extend(path for path in record['filenames'] if path.endswith('.wasm'))
if len(artifacts) != 1:
    raise SystemExit('Cargo did not report exactly one backend WASM artifact')
print(artifacts[0])
PY
)"
"$bindgen_bin" --target web --out-dir "$output/generated" --out-name backend "$artifact"
(cd "$output/generated" && shasum -a 256 backend.js backend_bg.wasm backend.d.ts backend_bg.wasm.d.ts > SHA256SUMS)
if [[ "$mode" == --check ]]; then
  diff -qr generated "$output/generated"
  echo 'Committed Solana WASM matches pinned source generation'
else
  mkdir -p generated
  cp "$output/generated/"* generated/
  cat generated/SHA256SUMS
fi
